def extract_raw_opcodes(bytecode):
    """
    Достает текстовую последовательность опкодов в сыром виде через \n, если ошибка - вернут None
    """
    try:
        opcodes = disassemble(bytecode)
        return opcodes

    except Exception as e:
        print(e)
        return None
